@startuml
class Employee {
  +name : string
  +socialSecurityNumber : string
}

class CreativeEmployee extends Employee {
  +hasOscar : boolean
}

class Director extends CreativeEmployee {
  +assistantName : string
}

class Actor extends CreativeEmployee {
  +education : string
}

class Technician extends Employee {
  +fieldOfActivity : string
}

class FilmSet {
}

class Film {
  +title : string
  +yearOfRelease : int
}

enum Genre {
  THRILLER
  ACTION
  HORROR
  COMEDY
}

class Screenwriter {
  +name : string
  +mostSuccessfulFilm : string
}

class Screenplay {
  +title : string
  +version : string
  +date : date
  +numberOfScenes : int
  +plot : string
}

class Novel {
  +title : string
  +author : string
}

class Concept {
}

Film "1" -- "*" FilmSet
FilmSet "*" -- "*" Film

Film "1" -- "1" Genre
Film "1" -- "1" Screenplay
Film "1" -- "1" Director : is directed by
Film "1" -- "*" Actor : features
Film "1" -- "1" Screenplay : is based on

Screenplay "1" -- "1" Screenwriter : is written by
Screenplay "0..1" -- "0..1" Novel : is based on
Screenplay "0..1" -- "0..1" Concept : is based on

Actor "1" -- "1" Screenplay : reads
@enduml

